const q = $('Inbox Sync Request').first().json.query || {};
const pan = String(q.pan || '').toUpperCase();
const me = String(q.me || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const REF = /Ref TDS\/([A-Z]{5}[0-9]{4}[A-Z])\/([A-Z]{4}[0-9]{5}[A-Z])\/([0-9]{4}-[0-9]{2})/;
const stripQuoted = t => {
  const lines = String(t || '').replace(/\r/g, '').split('\n');
  const out = [];
  for (const l of lines) {
    if (/^On .+wrote:\s*$/.test(l) || /^-{2,}\s*Original Message/i.test(l) || /^From:\s/.test(l) || /^_{5,}/.test(l)) break;
    if (/^>/.test(l)) continue;
    out.push(l);
  }
  return out.join('\n').trim().slice(0, 4000);
};
const htmlToText = h => String(h || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const items = $input.all();
const messages = [];
const seen = new Set();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const isGmail = j.labelIds !== undefined || j.headers !== undefined;
  const isOutlook = j.receivedDateTime !== undefined;
  if (!isGmail && !isOutlook) continue;
  const subject = String(j.subject || '');
  const m = subject.match(REF);
  if (!m || m[1] !== pan) continue;
  const id = String(j.id || j.messageId || '');
  if (!id || seen.has(id)) continue;
  seen.add(id);
  let from, fromName, to, date, body, direction;
  if (isGmail) {
    from = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '';
    fromName = (j.from && j.from.value && j.from.value[0] && j.from.value[0].name) || '';
    to = ((j.to && j.to.value) || []).map(v => v.address).join(', ');
    date = j.date ? new Date(j.date).toISOString() : '';
    body = stripQuoted(j.text || htmlToText(j.html));
    direction = (j.labelIds || []).includes('SENT') || me.includes(String(from).toLowerCase()) ? 'sent' : 'received';
  } else {
    from = (j.from && j.from.emailAddress && j.from.emailAddress.address) || '';
    fromName = (j.from && j.from.emailAddress && j.from.emailAddress.name) || '';
    to = (j.toRecipients || []).map(r => r.emailAddress && r.emailAddress.address).join(', ');
    date = j.receivedDateTime || j.sentDateTime || '';
    const c = (j.body && j.body.content) || j.bodyPreview || '';
    body = stripQuoted((j.body && j.body.contentType === 'html') ? htmlToText(c) : c);
    direction = me.includes(String(from).toLowerCase()) ? 'sent' : 'received';
  }
  const attachments = [];
  const bin = items[i].binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const name = b.fileName || key;
    if (!/pdf$/i.test(b.mimeType || '') && !/\.pdf$/i.test(name)) continue;
    if (attachments.length >= 5) break;
    try {
      const buf = await this.helpers.getBinaryDataBuffer(i, key);
      if (buf.length > 3 * 1024 * 1024) { attachments.push({ name, skipped: 'too large' }); continue; }
      attachments.push({ name, base64: buf.toString('base64') });
    } catch (e) { attachments.push({ name, skipped: 'unreadable' }); }
  }
  messages.push({ id, provider: isGmail ? 'gmail' : 'outlook', threadId: j.threadId || j.conversationId || '', subject, refPan: m[1], refTan: m[2], refFy: m[3], direction, from, fromName, to, date, body, attachments });
}
messages.sort((a, b) => String(a.date).localeCompare(String(b.date)));
return [{ json: { ok: true, pan, syncedAt: new Date().toISOString(), count: messages.length, messages } }];
